export function copperBorderSvg(lang, kind, mobile = false) {
  if (!["fr", "en"].includes(lang) || !COPPER_BORDER_KINDS.includes(kind) || typeof mobile !== "boolean") throw new TypeError("Invalid copper figure variant");
  return FIGURES[`${kind}-${lang}-${mobile ? "mobile" : "desktop"}`];
}
